//! Phase 9 engine conformance suite (plan §9.1).
//!
//! One suite every `SpeechProvider` must pass. It runs against a small
//! test-only provider so `cargo test -p teletype-speech --test conformance`
//! works with NO model files present; real engines stay behind their
//! feature flags and are never instantiated here.
//!
//! Wiring a real engine once its feature is on is one line, e.g.:
//!
//! ```ignore
//! run_conformance(&mut teletype_speech::WhisperProvider::new());
//! ```

use std::path::{Path, PathBuf};

use teletype_speech::{SpeechError, SpeechProvider};

/// Fixtures generated by `scripts/gen_speech_fixtures.sh` (16 kHz mono s16le).
fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

/// Decode a 16 kHz mono s16le WAV into f32 samples in [-1, 1].
fn read_wav_f32(path: &Path) -> Vec<f32> {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    assert_eq!(&bytes[0..4], b"RIFF", "not a RIFF file: {}", path.display());
    assert_eq!(
        &bytes[8..12],
        b"WAVE",
        "not a WAVE file: {}",
        path.display()
    );

    let mut offset = 12usize;
    let mut data: Option<&[u8]> = None;
    while offset + 8 <= bytes.len() {
        let chunk_id = &bytes[offset..offset + 4];
        let chunk_size =
            u32::from_le_bytes(bytes[offset + 4..offset + 8].try_into().unwrap()) as usize;
        if chunk_id == b"data" {
            let start = offset + 8;
            let end = (start + chunk_size).min(bytes.len());
            data = Some(&bytes[start..end]);
        }
        offset += 8 + chunk_size + chunk_size % 2; // data chunks are word-aligned
    }
    let data = data.expect("no data chunk");
    (0..data.len() / 2)
        .map(|i| {
            let s = i16::from_le_bytes([data[2 * i], data[2 * i + 1]]);
            s as f32 / 32768.0
        })
        .collect()
}

/// `run_conformance` needs a provider that behaves like a real engine on the
/// fixture corpus: real text for speech, `NoSpeech` for silence. The
/// library's `MockSpeechProvider` returns one canned transcript for every
/// input, so it cannot distinguish `silence.wav` — this local mock keys on
/// actual sample energy instead.
#[derive(Debug)]
struct ConformanceMock {
    loaded: bool,
}

impl ConformanceMock {
    fn new() -> Self {
        Self { loaded: false }
    }
}

impl SpeechProvider for ConformanceMock {
    fn load(&mut self, _path: &Path) -> Result<(), SpeechError> {
        self.loaded = true;
        Ok(())
    }

    fn unload(&mut self) {
        self.loaded = false;
    }

    fn is_loaded(&self) -> bool {
        self.loaded
    }

    fn transcribe(&mut self, samples: &[f32], _language: &str) -> Result<String, SpeechError> {
        if !self.loaded {
            return Err(SpeechError::NoModel);
        }
        // Above this RMS the input is "speech".
        let rms = (samples.iter().map(|s| s * s).sum::<f32>() / samples.len().max(1) as f32).sqrt();
        if rms < 0.001 {
            return Err(SpeechError::NoSpeech);
        }
        Ok("hello".to_string())
    }
}

/// The conformance suite: every provider must pass these, per plan §9.1.
pub fn run_conformance(provider: &mut dyn SpeechProvider) {
    // 1. Loads ok.
    provider
        .load(fixture("hello.wav").as_path())
        .expect("load must succeed");
    assert!(provider.is_loaded(), "is_loaded after load");

    // 2. hello.wav -> non-empty text.
    let hello = read_wav_f32(&fixture("hello.wav"));
    let text = provider
        .transcribe(&hello, "auto")
        .expect("hello.wav must transcribe");
    assert!(
        !text.trim().is_empty(),
        "hello.wav must yield non-empty text"
    );

    // 3. silence.wav -> NoSpeech error.
    let silence = read_wav_f32(&fixture("silence.wav"));
    match provider.transcribe(&silence, "auto") {
        Err(SpeechError::NoSpeech) => {}
        other => panic!("silence.wav must yield NoSpeech, got {other:?}"),
    }

    // 4. long_60s.wav -> completes without panic.
    let long = read_wav_f32(&fixture("long_60s.wav"));
    assert!(
        long.len() >= 55 * 16000,
        "long_60s.wav fixture must be >= 55 s"
    );
    let _ = provider.transcribe(&long, "auto");

    // 5. set_boost_terms round trip: accepted, no error, no crash on empty.
    provider
        .set_boost_terms(&[teletype_speech::BoostTerm {
            text: "Siobhan".into(),
            aliases: vec!["shivon".into()],
            weight: 1.0,
        }])
        .expect("set_boost_terms with a term must succeed");
    provider
        .set_boost_terms(&[])
        .expect("set_boost_terms with an empty list must not error");

    // 6. unload() ok.
    provider.unload();
    assert!(!provider.is_loaded(), "is_loaded after unload");
}

#[test]
fn test_provider_passes_conformance() {
    let mut provider = ConformanceMock::new();
    run_conformance(&mut provider);
}
